import requestService from 'api/request'
import Empty from 'components/elements/Empty'
import React, { useEffect, useState } from 'react'
import Countdown from 'react-countdown'
import { useTranslation } from 'react-i18next'

const Order = () => {
    const [orders, setOrders] = useState([])
    const { t } = useTranslation()
    const getOrders = async () => {
        try {
            const res = await requestService.get('/tickets/orders')
            if (res && res.data) {
                setOrders(res.data?.data)
            }
        } catch (error) {
            console.log('====================================');
            console.log(error);
            console.log('====================================');
        }
    }

    useEffect(() => {
        getOrders()
    }, [])
    return (
        <div data-v-cde322bf="" data-v-e697ea1f="" className="nft-list-page">

            <div data-v-cde322bf="" className="page-content">
                <div data-v-cde322bf="" className="nft-grid" >
                    {
                        orders?.length !== 0 &&
                        orders?.map((i: any) => (
                            <div data-v-cde322bf="" className="nft-item" key={i?._id}>
                                <div data-v-cde322bf="" className="nft-footer">
                                <div data-v-cde322bf="" className="nft-image">
                                    <div data-v-cde322bf="" className="van-image" >
                                        <img
                                            src={`${process.env.REACT_APP_BASE_URL}` + i?.ticket?.urlImage}
                                            alt="Vé vàng NFT"
                                            className="van-image__img"
                                            style={{ objectFit: "cover" }}
                                        />
                                        {/**/}
                                        {/**/}
                                    </div>
                                </div>
                                </div>
                                <div data-v-cde322bf="" className="nft-footer">
                                    <div data-v-cde322bf="" className="nft-info">
                                        <div data-v-cde322bf="" className="nft-title">
                                            <span data-v-cde322bf="" className="name">
                                                {i?.name}
                                            </span>
                                        </div>
                                        <div data-v-cde322bf="" className="countdown-wrapper">
                                            <span data-v-cde322bf="" className="label">
                                                {t("home.expiration_time")}：
                                            </span>
                                            <div data-v-cde322bf="" role="timer" className="van-count-down">
                                                <Countdown date={new Date(i?.soldOutAt)?.getTime()}
                                                    renderer={({ days, hours, minutes, seconds, completed }) => {
                                                        if (completed) {

                                                            return <div>Expired</div>;
                                                        } else {
                                                            return <span>{days} {t("home.day")} {hours}:{minutes}:{seconds}</span>;
                                                        }
                                                    }}
                                                />
                                            </div>
                                        </div>
                                        <div data-v-cde322bf="" className="nft-price">
                                            <span data-v-cde322bf="" className="price-label">
                                                {t("home.price")}
                                            </span>
                                            <span data-v-cde322bf="" className="price-value">
                                                {i?.price}$
                                            </span>
                                        </div>
                                        <div data-v-cde322bf="" className="nft-earnings">
                                            <div data-v-cde322bf="" className="earnings-item">
                                                <span data-v-cde322bf="" className="label">
                                                    {t("home.daily_income")}
                                                </span>
                                                <span data-v-cde322bf="" className="value">
                                                    +{i?.incomePerDay} $
                                                </span>
                                            </div>
                                            <div data-v-cde322bf="" className="earnings-item">
                                                <span data-v-cde322bf="" className="label">
                                                    {t("home.total_revenue")}
                                                </span>
                                                <span data-v-cde322bf="" className="value">
                                                    {i?.price + i?.incomePerDay * i?.earningDay} $
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                </div>
                            </div>
                        ))

                    }
                </div>
                {
                    orders?.length === 0 && <Empty title='order.no_empty_ticket' />
                }


                <div data-v-cde322bf="" className="float-button">
                    <i
                        data-v-cde322bf=""
                        className="van-badge__wrapper van-icon van-icon-records records-icon"
                    >
                        {/**/}
                        {/**/}
                        {/**/}
                    </i>
                    <span data-v-cde322bf="">Hồ sơ thu nhập</span>
                </div>
            </div>
            {/**/}
            {/**/}
            {/**/}
            {/**/}
            {/**/}
            {/**/}
        </div>

    )
}

export default Order
